"use strict";(globalThis.webpackChunkgrc||=[]).push([[90781],{69039(e){e.exports=JSON.parse('{"citeKey":"yin2013patterndirect","slug":"yin-2013-pattern-direct-320e","title":"Pattern-Direct and Layout-Aware Replication Scheme for Parallel I/O Systems","authors":["Y. Yin","J. Li","J. He","X.-H. Sun","R. Thakur"],"venue":"IEEE International Parallel and Distributed Processing Symposium (IPDPS\' 13), Phoenix, AZ, USA","type":"Conference","entryType":"inproceedings","date":"May, 2013","year":2013,"era":"iit","month":5,"doi":"10.1109/ipdps.2013.114","abstract":"The performance gap between computing power and the I/O system is ever increasing, and in the meantime more and more High Performance Computing (HPC) ap- plications are becoming data intensive. This study describes an I/O data replication scheme, named Pattern-Direct and Layout-Aware (PDLA) data replication scheme, to alleviate this performance gap. The basic idea of PDLA is replicating identified data access pattern, and saving these reorganized replications with optimized data layouts based on access cost analysis. A runtime system is designed and developed to integrate the PDLA replication scheme and existing parallel I/O system; a prototype of PDLA is implemented under the MPICH2 and PVFS2 environments. Experimental results show that PDLA is effective in improving data access performance of parallel I/O systems.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2013/yin-2013-pattern-direct-320e.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);